#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later

"""Write the Homebrew cask and formula after verifying a published release."""

import argparse
import hashlib
import re
import subprocess
import tempfile
from pathlib import Path

REPOSITORY = "https://github.com/lvndry/dubplate"
MACOS_NAMES = {
    11: "big_sur",
    12: "monterey",
    13: "ventura",
    14: "sonoma",
    15: "sequoia",
    26: "tahoe",
}

CASK = """\
# Generated by scripts/publish-homebrew.py in lvndry/dubplate.
cask "dubplate" do
  version "{version}"
  sha256 "{checksum}"

  url "{repository}/releases/download/v#{{version}}/Dubplate-#{{version}}.dmg"
  name "Dubplate"
  desc "Two-deck DJ software for live mixing"
  homepage "{repository}"

  depends_on arch: :arm64
  depends_on macos: :{minimum_macos}

  app "Dubplate.app"
end
"""

FORMULA = """\
# Generated by scripts/publish-homebrew.py in lvndry/dubplate.
class Dubplate < Formula
  desc "Analyze tracks, prepare DJ sets, and export to rekordbox"
  homepage "{repository}"
  url "{url}"
  sha256 "{checksum}"
  license "GPL-3.0-or-later"

  depends_on arch: :arm64
  depends_on macos: :{minimum_macos}

  def install
    bin.install "bin/dubplate"
  end

  test do
    assert_match "dubplate #{{version}}", shell_output("#{{bin}}/dubplate --version")
  end
end
"""


def download(base, name, directory):
    destination = directory / name
    subprocess.run(
        [
            "curl",
            "--fail",
            "--silent",
            "--show-error",
            "--location",
            "--retry",
            "3",
            "--output",
            str(destination),
            f"{base}/{name}",
        ],
        check=True,
    )
    return destination


def verified_checksum(base, asset, lines, directory):
    pattern = re.compile(r"([a-fA-F0-9]{64}) [ *]" + re.escape(asset))
    matches = [match[1].lower() for line in lines if (match := pattern.fullmatch(line))]
    if len(matches) != 1:
        raise SystemExit(f"SHA256SUMS does not give exactly one checksum for {asset}")
    path = download(base, asset, directory)
    sha256 = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            sha256.update(chunk)
    digest = sha256.hexdigest()
    if matches[0] != digest:
        raise SystemExit(f"checksum mismatch for {asset}: expected {matches[0]}, got {digest}")
    return digest


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("version", help="published release version, with an optional v prefix")
    parser.add_argument("tap", type=Path, help="checkout of lvndry/homebrew-dubplate")
    parser.add_argument("--minimum-macos", type=int, default=11, choices=MACOS_NAMES)
    args = parser.parse_args()
    version = args.version.removeprefix("v")
    if not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", version):
        parser.error("the version must have the form MAJOR.MINOR.PATCH")
    if not args.tap.is_dir():
        parser.error(f"tap directory does not exist: {args.tap}")

    base = f"{REPOSITORY}/releases/download/v{version}"
    disk_image = f"Dubplate-{version}.dmg"
    tarball = f"dubplate-{version}-aarch64-apple-darwin.tar.gz"
    with tempfile.TemporaryDirectory() as temp:
        directory = Path(temp)
        lines = download(base, "SHA256SUMS", directory).read_text().splitlines()
        cask_checksum = verified_checksum(base, disk_image, lines, directory)
        formula_checksum = verified_checksum(base, tarball, lines, directory)

    minimum_macos = MACOS_NAMES[args.minimum_macos]
    entries = {
        "Casks/dubplate.rb": CASK.format(
            version=version,
            checksum=cask_checksum,
            repository=REPOSITORY,
            minimum_macos=minimum_macos,
        ),
        "Formula/dubplate.rb": FORMULA.format(
            url=f"{base}/{tarball}",
            checksum=formula_checksum,
            repository=REPOSITORY,
            minimum_macos=minimum_macos,
        ),
    }
    for path, contents in entries.items():
        destination = args.tap / path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(contents, encoding="utf-8")
        print(f"Wrote {destination}")


if __name__ == "__main__":
    main()
